// kekOption allows management of the mutation configuration using functional options.
type kekOption func(*KEKMutation)

// newKEKMutation creates new mutation for the KEK entity.
func newKEKMutation(c config, op Op, opts ...kekOption) *KEKMutation {
	m := &KEKMutation{
		config:        c,
		op:            op,
		typ:           TypeKEK,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withKEKID sets the ID field of the mutation.
func withKEKID(id envelope.ID) kekOption {
	return func(m *KEKMutation) {
		var (
			err   error
			once  sync.Once
			value *KEK
		)
		m.oldValue = func(ctx context.Context) (*KEK, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().KEK.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withKEK sets the old KEK of the mutation.
func withKEK(node *KEK) kekOption {
	return func(m *KEKMutation) {
		m.oldValue = func(context.Context) (*KEK, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

